var msg_payload = msg.payload;

// ---------- BASIC VALIDATION ----------
if (!msg_payload || !Array.isArray(msg_payload.exited) || msg_payload.exited.length === 0) {
    return null;
}

// ---------- ROOT METADATA ----------
var timestamp = msg_payload.timestamp;
var scene_name = msg_payload.scene_name || "unknown_scene";
var region_name = msg_payload.region_name || "unknown_region";

var ts = new Date(timestamp);
var dateStr = ts.toISOString().split("T")[0];
var timeStr = ts.toTimeString().split(" ")[0].replace(/:/g, "");

// ---------- PROCESS EXITED VEHICLES ----------
msg_payload.exited.forEach(function (exitItem) {

    var obj = exitItem.object;
    if (!obj || obj.category !== "vehicle") return;

    // ---------- SPEED ----------
    var velocity = obj.velocity || [0, 0, 0];
    var vx = velocity[0] || 0;
    var vy = velocity[1] || 0;
    var speed = Math.sqrt(vx * vx + vy * vy) * 3.6;

    // ---------- BASE FIELDS ----------
    var fields = {
        object_id: obj.object_id ?? null,
        speed: parseFloat(speed.toFixed(2)),
        dwell: exitItem.dwell ? parseFloat(exitItem.dwell.toFixed(2)) : null,
        first_seen: obj.first_seen ?? null,
        confidence: obj.confidence ?? null
    };

    // ---------- TAGS ----------
    var tags = {
        scene_name: scene_name,
        region_name: region_name,
        category: obj.category,
        vehicle_type: obj.vehicle_type || "unknown"
    };

    // ---------- IMAGE DIRECTORY ----------
    var baseDir = `/images_data/vehicle-events/${dateStr}/${scene_name}`;
    fs.mkdirSync(baseDir, { recursive: true });

    // =====================================================
    // FRONT / REAR CAMERA (ANPR DATA)
    // =====================================================

    // Save front vehicle image if present
    if (obj.front_vehicle_image_b64) {
        var frontVehicleImgName = `vehicle_front_${obj.object_id}_${timeStr}.jpg`;
        fs.writeFileSync(`${baseDir}/${frontVehicleImgName}`, Buffer.from(obj.front_vehicle_image_b64, "base64"));
        fields.vehicle_front_image_url = `http://localhost:8081/vehicle-events/${dateStr}/${scene_name}/${frontVehicleImgName}`;
    }

    // Save rear vehicle image if present
    if (obj.rear_vehicle_image_b64) {
        var rearVehicleImgName = `vehicle_rear_${obj.object_id}_${timeStr}.jpg`;
        fs.writeFileSync(`${baseDir}/${rearVehicleImgName}`, Buffer.from(obj.rear_vehicle_image_b64, "base64"));
        fields.vehicle_rear_image_url = `http://localhost:8081/vehicle-events/${dateStr}/${scene_name}/${rearVehicleImgName}`;
    }

    // ---------- LICENSE PLATE: prefer front, fall back to rear ----------
    // If both cameras have a plate, pick the one with higher confidence.
    var frontPlate = obj.front_license_plate || null;
    var rearPlate  = obj.rear_license_plate  || null;
    var bestPlate  = null;

    // Store raw front/rear reads separately for audit/mismatch detection.
    if (frontPlate && frontPlate.text) {
        fields.front_plate_text       = frontPlate.text;
        fields.front_plate_confidence = frontPlate.confidence ?? null;
    }
    if (rearPlate && rearPlate.text) {
        fields.rear_plate_text       = rearPlate.text;
        fields.rear_plate_confidence = rearPlate.confidence ?? null;
    }

    if (frontPlate && rearPlate) {
        bestPlate = ((frontPlate.confidence || 0) >= (rearPlate.confidence || 0)) ? frontPlate : rearPlate;
    } else {
        bestPlate = frontPlate || rearPlate;
    }

    if (bestPlate && bestPlate.text && bestPlate.text.length >= 6) {
        fields.license_plate_text       = bestPlate.text;
        fields.license_plate_confidence = bestPlate.confidence ?? null;
    }

    // Save front plate image if present
    if (frontPlate && frontPlate.image_b64) {
        var frontPlateLabel = ((frontPlate.text || "unknown").replace(/[^A-Z0-9]/gi, "")) || "unknown";
        var frontPlateImgName = `plate_front_${frontPlateLabel}_${timeStr}.jpg`;
        fs.writeFileSync(`${baseDir}/${frontPlateImgName}`, Buffer.from(frontPlate.image_b64, "base64"));
        fields.front_plate_image_url = `http://localhost:8081/vehicle-events/${dateStr}/${scene_name}/${frontPlateImgName}`;
    }

    // Save rear plate image if present
    if (rearPlate && rearPlate.image_b64) {
        var rearPlateLabel = ((rearPlate.text || "unknown").replace(/[^A-Z0-9]/gi, "")) || "unknown";
        var rearPlateImgName = `plate_rear_${rearPlateLabel}_${timeStr}.jpg`;
        fs.writeFileSync(`${baseDir}/${rearPlateImgName}`, Buffer.from(rearPlate.image_b64, "base64"));
        fields.rear_plate_image_url = `http://localhost:8081/vehicle-events/${dateStr}/${scene_name}/${rearPlateImgName}`;
    }

    // =====================================================
    // SIDE VIEW CAMERA (AXLE DATA)
    // =====================================================
    if (obj.vehicle_color !== undefined) {
        fields.vehicle_color      = obj.vehicle_color      ?? null;
        fields.axle_count         = obj.axle_count         ?? null;
        fields.wheel_count        = obj.wheel_count        ?? null;
        fields.touching_ground    = obj.touching_ground    ?? null;
        fields.not_touching_ground = obj.not_touching_ground ?? null;
    }

    // Save left side-view image (currently the only side angle; right added when available)
    if (obj.left_vehicle_side_view_b64) {
        var sideImgName = `side_left_${obj.object_id}_${timeStr}.jpg`;
        fs.writeFileSync(`${baseDir}/${sideImgName}`, Buffer.from(obj.left_vehicle_side_view_b64, "base64"));
        fields.vehicle_side_view_url = `http://localhost:8081/vehicle-events/${dateStr}/${scene_name}/${sideImgName}`;
    }

    // ---------- SEND TO INFLUX ----------
    node.send({
        measurement: "smart_tolling_events",
        payload: [fields, tags],
        timestamp: timestamp
    });
});

return null;

// Check if exited exists and has at least one element
if (msg.payload && Array.isArray(msg.payload.exited) && msg.payload.exited.length > 0) {
    // Send only exited array to debug
    msg.payload = msg.payload;
    return msg;
}

// If no exited data, do nothing
return null;
